const nodeType = {
  DEFAULT: 0,
  NO_BORDER: 0,
  ROUNDED_RECT: 1,
  RECT: 2,
  CIRCLE: 3,
  CLOUD: 4,
  BANG: 5,
  HEXAGON: 6,
} as const;

public addNode(level: number, id: string, descr: string, type: number): void {
  log.info('addNode', level, id, descr, type);

  let isRoot = false;

  if (this.nodes.length === 0) {
    this.baseLevel = level;
    level = 0;
    isRoot = true;
  } else if (this.baseLevel !== undefined) {
    level = level - this.baseLevel;
    isRoot = false;
  }

  const node: MindmapNode = {
    id: this.count++,
    nodeId: sanitizeText(id, conf),
    level,
    descr: sanitizeText(descr, conf),
    type,
    children: [],
    width: conf.mindmap?.maxNodeWidth ?? defaultConfig.mindmap.maxNodeWidth,
    padding,
    isRoot,
  };

  const parent = this.getParent(level);
  if (parent) {
    parent.children.push(node);
    this.nodes.push(node);
  } else {
    if (isRoot) {
      this.nodes.push(node);
    } else {
      throw new Error(
        `There can be only one root. No parent could be found for ("${node.descr}")`
      );
    }
  }
}

public getType(startStr: string, endStr: string) {
  log.debug('In get type', startStr, endStr);
  switch (startStr) {
    case '[':
      return this.nodeType.RECT;
    case '(':
      return endStr === ')' ? this.nodeType.ROUNDED_RECT : this.nodeType.CLOUD;
    case '((':
      return this.nodeType.CIRCLE;
    case ')':
      return this.nodeType.CLOUD;
    case '))':
      return this.nodeType.BANG;
    case '{{':
      return this.nodeType.HEXAGON;
    default:
      return this.nodeType.DEFAULT;
  }
}

// Map mindmap node type to valid shape name
const getShapeFromType = (type: number) => {
  const theme = conf.theme?.toLowerCase() ?? '';
  const isReduxTheme = theme.includes('redux');
  switch (type) {
    case nodeType.CIRCLE:
      return 'mindmapCircle';
    case nodeType.RECT:
      return 'rect';
    case nodeType.ROUNDED_RECT:
      return 'rounded';
    case nodeType.CLOUD:
      return 'cloud';
    case nodeType.BANG:
      return 'bang';
    case nodeType.HEXAGON:
      return 'hexagon';
    case nodeType.DEFAULT:
      return isReduxTheme ? 'rounded' : 'defaultMindmapNode';
    case nodeType.NO_BORDER:
    default:
      return 'rect';
  }
};

